"""Render the command reference of the guide from the command line itself, so it cannot go stale.

``python scripts/reference.py`` prints the page; ``just reference`` writes it, and a test fails when the
committed page differs (openspec: cli, docs/EVOLVING.md).
"""

from typing import Any

import typer

from lookout.bootstrap.main import app

HEADER = (
    "<!-- Generated by scripts/reference.py from the command line. Do not edit: run `just reference`. -->"
)


def _values(param: Any) -> str:  # noqa: ANN401 - Typer vendors click, so its types are not importable
    choices = getattr(param.type, "choices", None)
    return f" One of: {', '.join(f'`{c}`' for c in choices)}." if choices else ""


def _option(param: Any) -> str:  # noqa: ANN401
    names = ", ".join(f"`{o}`" for o in param.opts)
    values = _values(param)
    unset = (None, False, (), "")
    default = f" Default: `{param.default}`." if not param.required and param.default not in unset else ""
    return f"| {names} | {param.help or ''}{values}{default} |"


def render() -> str:
    """The whole page, as Markdown."""
    group: Any = typer.main.get_command(app)
    lines = [
        "# Commands",
        "",
        HEADER,
        "",
        "Every command accepts `--config PATH` (or `LOOKOUT_CONFIG`) before its name to choose the",
        "configuration file, and `--help`.",
        "",
    ]
    for name in sorted(group.commands):
        command = group.commands[name]
        lines += [f"## `lookout {name}`", "", (command.help or "").strip(), ""]
        arguments = [p for p in command.params if p.param_type_name == "argument"]
        options = [p for p in command.params if p.param_type_name == "option" and "--help" not in p.opts]
        if arguments:
            lines += ["| Argument | |", "| --- | --- |"]
            lines += [f"| `{p.name}` | {p.help or ''}{_values(p)} |" for p in arguments]
            lines.append("")
        if options:
            lines += ["| Option | |", "| --- | --- |"]
            lines += [_option(p) for p in options]
            lines.append("")
    return "\n".join(lines).rstrip() + "\n"


if __name__ == "__main__":
    print(render(), end="")  # noqa: T201
